script:
import { createTimeline } from "animejs";

// Four services in a row, drawn as C4 nodes; a token carries the request.
const services = [
  { id: "client", kind: "person", label: "Client", x: 20 },
  { id: "api", kind: "container", label: "API", tag: "Container · Node.js", x: 195 },
  { id: "cache", kind: "database", label: "Cache", tag: "Database · Redis", x: 370 },
  { id: "db", kind: "database", label: "Orders", tag: "Database · Postgres", x: 545 },
];

document.head.insertAdjacentHTML("beforeend", `<style>
  .token { position: absolute; top: 96px; left: 0; width: 12px; height: 12px; border-radius: 50%; background: light-dark(#2b55e6, #5b7cff); }
  .token.response { background: light-dark(#1b9a57, #4ed990); }
  .wire { position: absolute; top: 160px; left: 95px; width: 525px; border-top: 1.5px dashed light-dark(#c8ccd3, #39404d); }
</style>`);

document.body.insertAdjacentHTML("beforeend", '<div class="wire"></div>');

const nodes = new Map(
  services.map(({ id, ...service }) => [id, wb.node({ ...service, y: 128, width: 150, height: 64 })]),
);

const token = document.createElement("div");
token.className = "token";
document.body.append(token);

const centre = (id) => services.find((service) => service.id === id).x + 75 - 6;

// Where the request is lights up; services it has not reached are dimmed.
const show = (at, involved) => {
  for (const [id, node] of nodes)
    node.dataset.state = id === at ? "active" : involved.includes(id) ? "default" : "dimmed";
};

// One paused anime.js timeline for the token's whole journey. Each chapter
// spends its first 70% travelling to where its data says, then rests.
const chapters = wb.chapters;
const motion = createTimeline({ autoplay: false, defaults: { ease: "inOutQuad" } });
motion.set(token, { translateX: centre(chapters[0].data.at) }, 0);

let start = 0;
for (const chapter of chapters) {
  motion.add(token, { translateX: centre(chapter.data.at), duration: chapter.duration * 0.7 }, start);
  start += chapter.duration;
}

// Draw exactly the moment the player asks for; time can jump either way.
wb.onTime((time, { chapter, chapterIndex, chapterTime }) => {
  motion.seek(time);

  // A service lights up once the token arrives, not as the chapter starts.
  const arrived = chapterTime >= chapter.duration * 0.7 || chapterIndex === 0;
  const at = arrived ? chapter.data.at : chapters[chapterIndex - 1].data.at;

  show(at, chapter.data.involved);
  token.classList.toggle("response", chapter.data.response);
});
